    /* =====================================================================
       部品の枠で引くための照合。
       位置は IDS の先頭の記述演算子で決め、その引数の中にある部品は何段下でもその位置に入れる。
       倣（⿰亻放）の旁は 放 で、放（⿰方攵）の 方 と 攵 も旁の範囲にあるので、旁に 放 でも 攵 でも当たる。
       さらに偏・旁・冠・脚は、部品が字のどこにあるかでも決める。IDS を入れ子のまま枠に割り付け、
       左半分に収まれば偏、上半分に収まれば冠…とする。椅（⿰木奇、奇=⿱大可）の 大 は右上にあるので、
       旁であり冠でもある（利用者は「上にある部品＝冠」と見る）。
       ===================================================================== */
