      196: "䳄䳑䴇鳥鳩鴂鴃鴆鴇鴎鴑鴒鴕鴘鴛鴝鴞鴟鴣鴦鴨鴲鴾鴿鵁鵂鵇鵊鵐鵑鵜鵝鵞鵟鵠鵡鵣鵩鵫鵬鵯鵰鵲鵳鵶鵷鵺鵼鵾鶇鶉鶊鶍鶏鶖鶙鶚鶡鶤鶩鶫鶬鶯鶲鶴鶵鶸鶹鶺鶼鶽鶿鷀鷁鷂鷃鷄鷆鷉鷏鷓鷖鷗鷙鷚鷟鷣鷦鷧鷭鷯鷲鷴鷸鷺鷽鸇鸊鸍鸕鸙鸚鸛鸜鸝鸞𩿎𪀚𪀯𪂂𪃹𪆐",
      197: "鹵鹸鹹鹻鹼",
      198: "鹿麁麅麈麌麑麒麓麕麗麛麝麞麟麤",
      199: "麥麦麨麩麪麭麯麴麸麹𪎌",
      200: "麻麽麿",
